(()=>{'use strict';if(new URLSearchParams(location.search).get('lang')!=='zh-Hans')return;document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-kaikai-brief]').forEach(card=>{const set=(s,t)=>{const el=card.querySelector(s);if(el)el.textContent=t};if(card.dataset.kaikaiBrief==='media'){set('.home-media-pastel-label','DAILY BRIEF · 法律判读');set('.home-media-report-meta span','每日护童快报');set('h3 a','剀剀案定谳后：阅览评议单能翻案吗？');set('.home-media-report-copy p','从评议意见阅览到再审门槛，并对照台湾定谳后成功平反案例。');set('.home-media-report-source','公开司法程序整理・非真实儿童肖像');set('.home-media-report-action','阅读完整快报 →')}else{set('small','09.18 · 每日护童快报・置顶');set('strong','剀剀案定谳后：阅览评议单能翻案吗？');set('em','从可阅览、不可复制的评议意见，到再审门槛与台湾平反案例。')}})})})();